function esc(s) { return String(s || '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;'); }
function pagina(titulo, corpo) {
  return '<!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>' + esc(titulo) + '</title>'
    + '<style>body{font-family:system-ui,sans-serif;max-width:520px;margin:24px auto;padding:0 16px;color:#1f2a2e;background:#f7f5f0}'
    + 'textarea{width:100%;box-sizing:border-box;min-height:220px;font:16px/1.5 system-ui,sans-serif;padding:12px;border:1px solid #ccc;border-radius:12px;background:#fff}'
    + 'button{width:100%;margin-top:16px;padding:14px;font-size:17px;border:0;border-radius:10px;background:#1f6f5c;color:#fff}'
    + '.av{background:#fff4d6;border:1px solid #e8c766;border-radius:10px;padding:10px 12px;margin:12px 0}'
    + 'p.m{color:#666;font-size:14px}</style></head><body><h2>' + esc(titulo) + '</h2>' + corpo + '</body></html>';
}
function validar(lead, token) {
  const wf = ((lead && lead.custom_fields) || {}).wf02 || {};
  const p = wf.pendente || null;
  if (!lead || !lead.id) return { ok: false, motivo: 'Lead não encontrado.' };
  if (!p || !p.token || p.token !== token) return { ok: false, motivo: 'Link inválido, já usado ou substituído por uma sugestão mais nova.' };
  if (p.criado_em && (Date.now() - new Date(p.criado_em).getTime()) > 48 * 3600 * 1000) return { ok: false, motivo: 'Link vencido (mais de 48 horas).' };
  return { ok: true, p };
}
const q = $('Abrir Link (GET)').first().json.query || {};
const lead = $('Ler Lead (GET)').first().json;
const novas = $input.all().map(i => i.json).filter(m => m && m.id);
const v = validar(lead, String(q.t || ''));
let html;
if (!v.ok) {
  html = pagina('Não dá pra enviar', '<p>' + esc(v.motivo) + '</p>');
} else {
  const jaRespondeu = novas.some(m => m.direction === 'outbound');
  const leadEscreveu = novas.some(m => m.direction === 'inbound');
  let avisos = '';
  if (jaRespondeu) avisos += '<div class="av">⚠️ Já saiu mensagem sua nessa conversa depois desta sugestão. Se enviar, vai repetir.</div>';
  if (leadEscreveu) avisos += '<div class="av">⚠️ O lead mandou mensagem nova depois desta sugestão. Confira a conversa antes de enviar.</div>';
  html = pagina('Enviar pelo 2144?', '<p class="m">Para: ' + esc(v.p.empresa || v.p.telefone) + (v.p.modo === 'followup' ? ' · follow-up ' + esc(v.p.fu_n) + '/2' : '') + '</p>' + avisos
    + '<form method="POST"><input type="hidden" name="lead" value="' + esc(lead.id) + '"><input type="hidden" name="t" value="' + esc(q.t) + '">'
    + '<textarea name="texto">' + esc(v.p.texto) + '</textarea>'
    + '<button type="submit">Enviar mensagem</button></form>'
    + '<p class="m">Pode editar o texto antes de enviar. Sai pelo mesmo número do primeiro contato e fica registrado no CRM.</p>'
    + (v.p.motivo ? '<p class="m">Leitura do copiloto: ' + esc(v.p.motivo) + '</p>' : ''));
}
return [{ json: { html } }];

function esc(s) { return String(s || '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;'); }
function pagina(titulo, corpo) {
  return '<!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>' + esc(titulo) + '</title>'
    + '<style>body{font-family:system-ui,sans-serif;max-width:520px;margin:24px auto;padding:0 16px;color:#1f2a2e;background:#f7f5f0}p.m{color:#666;font-size:14px}</style></head><body><h2>' + esc(titulo) + '</h2>' + corpo + '</body></html>';
}
const b = $('Confirmar Envio (POST)').first().json.body || {};
const lead = $input.first().json;
const wf = ((lead && lead.custom_fields) || {}).wf02 || {};
const p = wf.pendente || null;
let motivo = '';
if (!lead || !lead.id) motivo = 'Lead não encontrado.';
else if (!p || !p.token || p.token !== String(b.t || '')) motivo = 'Link inválido, já usado ou substituído por uma sugestão mais nova.';
else if (p.criado_em && (Date.now() - new Date(p.criado_em).getTime()) > 48 * 3600 * 1000) motivo = 'Link vencido (mais de 48 horas).';
const texto = String(b.texto || (p && p.texto) || '').replace(/\r\n/g, '\n').trim();
if (!motivo && !texto) motivo = 'Texto vazio.';
if (!motivo && texto.length > 2000) motivo = 'Texto muito longo (mais de 2000 caracteres).';
if (motivo) return [{ json: { ok: false, html: pagina('Não enviado', '<p>' + esc(motivo) + '</p>') } }];
return [{ json: { ok: true, lead_id: lead.id, custom_fields: lead.custom_fields || {}, p, texto, editado: texto !== String(p.texto || '').trim() } }];

function esc(s) { return String(s || '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;'); }
const NL = String.fromCharCode(10);
const v = $('Validar Envio').first().json;
const cf = v.custom_fields || {};
const prev = cf.wf02 || {};
const agora = new Date().toISOString();
const nota = '[' + agora + '] WF02b: sugestão do copiloto enviada pelo link (' + (v.editado ? 'editada pelo Hamilton' : 'sem edição') + ').';
const wf02 = Object.assign({}, prev, { ultimo_envio_em: agora, ultimo_envio_texto: v.texto, log: ((prev.log || '') + NL + nota).trim().split(NL).slice(-30).join(NL) });
delete wf02.pendente;
const html = '<!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Enviada</title>'
  + '<style>body{font-family:system-ui,sans-serif;max-width:520px;margin:24px auto;padding:0 16px;color:#1f2a2e;background:#f7f5f0}.box{background:#fff;border:1px solid #ddd;border-radius:12px;padding:16px;white-space:pre-wrap;line-height:1.5}p.m{color:#666;font-size:14px}</style></head><body>'
  + '<h2>Mensagem enviada ✅</h2><div class="box">' + esc(v.texto) + '</div><p class="m">Enviada pelo 2144 para ' + esc(v.p.empresa || v.p.telefone) + ' e registrada no CRM.</p></body></html>';
return [{ json: { lead_id: v.lead_id, patch_body: JSON.stringify({ custom_fields: Object.assign({}, cf, { wf02 }) }), html } }];
